mapper.select:
SELECT v.*, r.exam_date AS exam_date
FROM exam_value v
JOIN exam_record r ON v.record_id = r.id
WHERE r.user_id = #{userId}
  AND v.indicator_id = #{indicatorId}
  AND v.value_decimal IS NOT NULL

    AND r.exam_date >= #{startDate}


    AND r.exam_date <= DATE_ADD(#{endDate}, INTERVAL 1 DAY)

ORDER BY r.exam_date ASC
